<?phpnamespace app\api\service\business;use app\api\service\CommService;use app\common\model\business\MallOrder;class OrderService extends CommService{    public function __construct($param, $user_info)    {        parent::_initialize($param, $user_info);    }    public function createOrder()    {        $orderModel = new MallOrder();        $this->data['order_sn'] = $orderModel->createOrder($this->param, $this->user_info->customer_id);        return $this->data;    }    public function getOrderList()    {        $where['customer_id'] = $this->user_info->customer_id;        $where['status'] = $this->param['status'];        $order_list = MallOrder::where($where)->field('order_id,order_sn,service_type_id,hospital_id,patient_name,doctor_name,service_time,status,service_fee,actual_pay,create_time')            ->with(['hospital', 'serviceType'])            ->select();        $this->data['order_list'] = $order_list;        return $this->data;    }    public function getOrderInfo()    {        $order = MallOrder::where('order_id', $this->param['order_id'])            ->where('customer_id', $this->user_info->customer_id)            ->with(['hospital', 'serviceType', 'files'])//            ->with(['hospital', 'department', 'serviceType', 'files'])            ->find();        $this->data['order_info'] = $order;        return $this->data;    }    public function cancelOrder()    {        $order = MallOrder::where('order_id', $this->param['order_id'])            ->where('customer_id', $this->user_info->customer_id)            ->whereIn('status', [0, 1])            ->find();        if (!$order) {            throwError('订单不存在或状态错误', 401);        }        $order->status = 4;        $order->save();        return $this->data;    }    public function uploadCode()    {        $order = MallOrder::where('order_id', $this->param['order_id'])            ->where('customer_id', $this->user_info->customer_id)            ->where('status', 0)            ->find();        if (!$order) {            throwError('订单不存在或状态错误', 401);        }        $order->visit_code = $this->param['visit_code'];        $order->save();        return $this->data;    }    public function refundOrder()    {        $order = MallOrder::where('order_id', $this->param['order_id'])            ->where('customer_id', $this->user_info->customer_id)            ->where('status', 5)            ->find();        if (!$order) {            throwError('订单不存在或状态错误', 401);        }        $order->status = 30;        $order->save();        return $this->data;    }}